using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CityGroundAudit{static CityGroundAudit(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CityGroundAudit.request"))return;File.Delete("CityGroundAudit.request");try{var s=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var rs=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&r.GetComponent<MeshFilter>()&&r.GetComponent<MeshFilter>().sharedMesh).ToArray();var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/3D/Fbx/Materials/Pathways.mat");var grounds=rs.Where(r=>r.sharedMaterials.Contains(mat)).ToArray();var sb=new StringBuilder();sb.AppendLine("Ground Pathways renderers="+grounds.Length);foreach(var r in grounds){var f=r.GetComponent<MeshFilter>();var d=typeof(FinalPNGCityDetails).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{f.sharedMesh});var uv=((Vector2[][])d.GetType().GetField("uv").GetValue(d))[0];sb.AppendLine("GROUND "+r.name+" bounds="+r.bounds+" mesh="+AssetDatabase.GetAssetPath(f.sharedMesh)+" uv="+uv.Min(u=>u.x)+","+uv.Min(u=>u.y)+" to "+uv.Max(u=>u.x)+","+uv.Max(u=>u.y));var near=rs.Where(b=>b!=r&&b.bounds.size.y>3&&b.bounds.size.x>5&&b.bounds.size.z>5&&b.bounds.Intersects(new Bounds(r.bounds.center+Vector3.up*5,r.bounds.size+Vector3.up*20))).OrderByDescending(b=>b.bounds.size.x*b.bounds.size.z).Take(5);foreach(var b in near)sb.AppendLine(" BUILDING "+b.name+" "+b.bounds+" mat="+b.sharedMaterial?.name);}
foreach(var r in rs.Where(r=>r.name.ToLower().Contains("fuel")||r.name.ToLower().Contains("petrol")||r.name.Contains("Circus_Circus")))sb.AppendLine("LANDMARK "+r.name+" "+r.bounds+" mat="+r.sharedMaterial?.name);File.WriteAllText("FinalEnvironmentRoadReview/CityGroundAudit.txt",sb.ToString());}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/CityGroundAudit.txt",e.ToString());}}}
